Step 7: Handle Errors and Edge Cases
The API returns four error codes you need to handle: INVALID_PARAMS
(400), UNSUPPORTED_CHAIN
(400), RATE_LIMITED
(429), and UPSTREAM_ERROR
(502). Add retry logic for transient errors:
Future<SwapResult> getSwapWithRetry({
required int chainId,
required String tokenIn,
required String tokenOut,
required String amount,
required String sender,
int maxRetries = 3,
}) async {
for (var i = 0; i < maxRetries; i++) {
try {
return await getSwapQuote(
chainId: chainId,
tokenIn: tokenIn,
tokenOut: tokenOut,
amount: amount,
sender: sender,
);
} on SwapApiException catch (e) {
if (e.code == "RATE_LIMITED") {
await Future.delayed(
Duration(seconds: (i + 1) * 5),
);
continue;
}
if (e.code == "UPSTREAM_ERROR" && i < maxRetries - 1) {
await Future.delayed(
Duration(seconds: (i + 1) * 2),
);
continue;
}
rethrow;
}
}
throw SwapApiException(
code: "MAX_RETRIES",
message: "Failed after $maxRetries attempts",
);
}
